import sys


def is_sorted_ascending(values):
    for i in range(len(values) - 1):
        if values[i] > values[i + 1]:
            return False
    return True


data = sys.stdin.read().split()
n = int(data[0])
values = list(map(int, data[1:1 + n]))
print(is_sorted_ascending(values))

