import sys


def occurrences_of(values, x):
    lo, hi = 0, len(values) - 1
    first = -1
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == x:
            first = mid
            hi = mid - 1
        elif values[mid] < x:
            lo = mid + 1
        else:
            hi = mid - 1
    if first == -1:
        return 0
    lo, hi = first, len(values) - 1
    last = first
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == x:
            last = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return last - first + 1


data = sys.stdin.read().split()
n = int(data[0])
values = list(map(int, data[1:1 + n]))
x = int(data[1 + n])
print(occurrences_of(values, x))

import sys


def rotated_search(values, target):
    lo, hi = 0, len(values) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if values[mid] == target:
            return mid
        if values[lo] <= values[mid]:
            if values[lo] <= target < values[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if values[mid] < target <= values[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1


data = sys.stdin.read().split()
n = int(data[0])
values = list(map(int, data[1:1 + n]))
target = int(data[1 + n])
print(rotated_search(values, target))
